  readonly totalConsentimentoPendente: number;
}

/** Pessoa da organização cujo acesso aguarda liberação pela plataforma, com nome, situação, contatos e dados mínimos que faltam. */
export interface PessoaAguardandoLiberacao {
  id: string;
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
    base: {
      readonly contacts: string;
    };
    inicio: {
      readonly dadosFaltantes: string[];
    };
  };
}

export interface Inicio_responsavelContracts {
  /**
   * Finalidade: Carrega, ao abrir o Início do responsável, a situação de preparo da empresa e os números de acesso das pessoas da organização.
   * Entrada: Nenhuma entrada: a empresa e a organização vêm da sessão do responsável.
   * Processamento: Lê a empresa da organização da sessão e calcula (inicio.verificarPreparo) preparada e dadosFaltantes conforme empresaPreparadaDadosObrigatorios: nome, documento, ao menos um endereço e ao menos um contato; dadosFaltantes lista só o que a plataforma ainda não tem (naoPedirDadoJaExistente). Para as pessoas com papel inicio.PessoaOrganizacao da organização, calcula acessoCompleto e dadosFaltantes conforme acessoCompletoDadosMinimos (nome, país e consentimento quando o país é Brasil ou UE; telefone não conta) e conta: quantas têm acesso completo, quantas têm dados faltando e quantas têm consentimento exigido ainda pendente. Valores derivados são calculados, nunca gravados.
   * Saída: empresa: id, nome, indicador de preparada e lista de dados obrigatórios que faltam. indicadores: os três totais já calculados.
   */
  'inicio.inicio_responsavel.qryPainelResponsavel': {
    kind: 'qry';
    input: {};
    output: { empresa: SituacaoEmpresa; indicadores: IndicadoresAcessoPessoas };
    rules: ['empresaPreparadaDadosObrigatorios', 'naoPedirDadoJaExistente', 'acessoCompletoDadosMinimos'];
    access: { actors: ['responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso']; scope: 'organization' };
  };
  /**
   * Finalidade: Lista, por páginas, as pessoas da organização que aguardam o responsável liberar o acesso.
   * Entrada: page: número da página pedida; pageSize: quantidade de pessoas por página.
   * Processamento: Filtra as pessoas da organização do responsável com papel inicio.PessoaOrganizacao cuja situação na plataforma não está ativa (Inactive ou Blocked), ou seja, que aguardam a liberação da plataforma; o Início não guarda pendência nem decide a ligação do login (ligacaoLoginPelaPlataforma). Calcula dadosFaltantes de cada pessoa conforme acessoCompletoDadosMinimos. Não expõe o consentimento de privacidade (negado pelo grant). Ordena pelo nome.
   * Saída: pessoas: página { items, page, pageSize, hasMore } com id, nome, situação, contatos e dados mínimos que faltam de cada pessoa.
   */
  'inicio.inicio_responsavel.qryPessoasAguardandoLiberacao': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { pessoas: { items: PessoaAguardandoLiberacao[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['ligacaoLoginPelaPlataforma', 'acessoCompletoDadosMinimos', 'dadosNaoConcedemPermissoes'];
    access: { actors: ['responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/inicio/web/contracts/meu_cadastro.defs.ts" enhancement="_blank"/>

/** A empresa da organização à qual a pessoa está ligada, com o nome que a pessoa pode ver. */
export interface EmpresaDaPessoa {
  details: {
    identification: {
      name: string;
    };
  };
}

/** O cadastro da própria pessoa na organização, com a situação do acesso, os dados mínimos que faltam, os contatos, os vínculos e a empresa a que pertence. */
export interface MeuCadastro {
  id: string;
  version: number;
  details: {
    identification: {
      name?: string;
      countryCode?: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
    base: {
      readonly contacts: string;
      readonly relationshipRefs: string;
    };
    inicio: {
      readonly acessoCompleto: boolean;
      readonly dadosFaltantes: string;
      readonly consentimentoExigido: boolean;
    };
  };
  readonly aguardaLiberacao: boolean;
  empresa: EmpresaDaPessoa;
}

export interface Meu_cadastroContracts {
  /**
   * Finalidade: Carrega, em uma só chamada, o cadastro da pessoa logada na organização com a situação do acesso, o que falta, o aviso de liberação e o andamento do pedido.
   * Entrada: Nenhuma entrada: a pessoa é a da sessão, resolvida pela plataforma (locate.byLogin).
   * Processamento: Lê o PessoaOrganizacao da sessão (read.byId) e o nome da Empresa ligada por AssignedTo. Calcula, sem gravar, acessoCompleto, dadosFaltantes e consentimentoExigido conforme acessoCompletoDadosMinimos (nome e país, e consentimento válido se o país for Brasil ou União Europeia; telefone não conta) e naoPedirDadoJaExistente (só lista o que a plataforma ainda não tem). Calcula aguardaLiberacao a partir da situação, dos contatos e dos vínculos quando já existe outro cadastro com o mesmo e-mail, sem guardar pendência nem decidir a ligação (ligacaoLoginPelaPlataforma); como é recalculado a cada leitura, o aviso persiste em outro navegador (repetirNaoDuplicaPessoa). O e-mail da conta vem nos contatos apenas para exibição (emailContaNaoEditavel). acessoCompleto verdadeiro indica que a pessoa pode seguir direto aos módulos (seguirDiretoSeCompleto).
   * Saída: meuCadastro: o cadastro atual da pessoa com id, versão, nome, país, situação, contatos, vínculos, acesso completo, dados que faltam, consentimento exigido, indicador de aguardar liberação e o nome da empresa.
   */
  'inicio.meu_cadastro.qryMeuCadastro': {
    kind: 'qry';
    input: {};
    output: { meuCadastro: MeuCadastro };
    rules: ['acessoCompletoDadosMinimos', 'naoPedirDadoJaExistente', 'ligacaoLoginPelaPlataforma', 'seguirDiretoSeCompleto', 'repetirNaoDuplicaPessoa', 'emailContaNaoEditavel'];
    access: { actors: ['pessoaOrganizacao', 'responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso', 'pessoaCompletarMeuAcesso', 'pessoaVerEmpresa']; scope: 'organization' };
  };
  /**
   * Finalidade: Grava no próprio cadastro da pessoa logada os dados mínimos que faltavam.
   * Entrada: id e version: o cadastro da pessoa e a versão lida, para concorrência otimista. details.identification.name: nome, quando faltava. details.identification.countryCode: país ISO 3166-1 alfa-2, quando faltava. details.person.privacyConsent: consentimento de privacidade, enviado quando o país exige (Brasil ou União Europeia).
   * Processamento: Recusa se o id não for o cadastro da pessoa da sessão ou se a versão estiver desatualizada. Atualiza pelo PessoaOrganizacao.update apenas os campos ainda vazios, sem sobrescrever o que a plataforma já tem (naoPedirDadoJaExistente). Recusa qualquer alteração do e-mail da conta (emailContaNaoEditavel). Exige consentimento quando o país informado ou existente é Brasil ou União Europeia (acessoCompletoDadosMinimos). É idempotente: repetir o envio atualiza o mesmo cadastro e nunca cria outra pessoa nem outro vínculo (repetirNaoDuplicaPessoa). Não concede papéis nem permissões (dadosNaoConcedemPermissoes). acessoCompleto, dadosFaltantes e consentimentoExigido são recalculados, nunca gravados.
   * Saída: meuCadastro: o cadastro da pessoa no novo estado, com a nova versão, o acesso completo e os dados que ainda faltam recalculados, contatos, vínculos, aviso de liberação e nome da empresa.
   */
  'inicio.meu_cadastro.salvarMeusDados': {
    kind: 'cmd';
    writes: 'PessoaOrganizacao.update';
    input: { id: string; version: number; details: { identification: { name?: string; countryCode?: string }; person: { privacyConsent?: string } } };
    output: { meuCadastro: MeuCadastro };
    rules: ['acessoCompletoDadosMinimos', 'naoPedirDadoJaExistente', 'emailContaNaoEditavel', 'repetirNaoDuplicaPessoa', 'dadosNaoConcedemPermissoes'];
    access: { actors: ['pessoaOrganizacao', 'responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso', 'pessoaCompletarMeuAcesso', 'pessoaVerEmpresa']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/inicio/web/contracts/pessoas_organizacao.defs.ts" enhancement="_blank"/>

/** Situação de preparo da empresa dona do app: se está preparada e quais dados obrigatórios ainda faltam. */
export interface EmpresaPreparo {
  id: string;
  details: {
    inicio: {
      readonly preparada: boolean;
      readonly dadosFaltantes: string[];
    };
  };
}

/** Pessoa da organização em forma resumida: nome, país, situação na plataforma e situação do acesso. */
export interface PessoaResumo {
  id: string;
  details: {
    identification: {
      name: string;
      countryCode: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
    inicio: {
      readonly acessoCompleto: boolean;
      readonly dadosFaltantes: string[];
    };
  };
}

/** Canal de contato ligado à pessoa: o e-mail da conta autenticada ou o telefone opcional. */
export interface ContatoPessoa {
  details: {
    base: {
      readonly contacts: string;
    };
  };
}

/** Pessoa da organização com dados, contatos, situação do acesso, o que falta, exigência de consentimento e etapa da liberação do acesso. */
export interface PessoaDetalhe {
  id: string;
  details: {
    identification: {
      name: string;
      countryCode: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
    inicio: {
      readonly acessoCompleto: boolean;
      readonly dadosFaltantes: string[];
      readonly consentimentoExigido: boolean;
    };
  };
  contacts: ContatoPessoa[];
  readonly etapaLiberacao: 'pedidoEncaminhado' | 'acessoLiberado' | 'loginLigado' | 'acessoCompletado';
}

export interface Pessoas_organizacaoContracts {
  /**
   * Finalidade: Carrega de uma vez a situação de preparo da empresa do responsável e a primeira página das pessoas da organização.
   * Entrada: page: número da página da lista de pessoas (começa em 1); pageSize: quantidade de pessoas por página.
   * Processamento: Resolve a empresa da organização do responsável logado e calcula preparada e dadosFaltantes conforme empresaPreparadaDadosObrigatorios (nome, documento, ao menos um endereço e ao menos um contato). Lista as pessoas com o papel inicio.PessoaOrganizacao ligadas à empresa (locate.byTag/listLinks), ordenadas com as de acesso incompleto primeiro e depois por nome; para cada uma calcula acessoCompleto e dadosFaltantes conforme acessoCompletoDadosMinimos (nome, país e consentimento válido se Brasil/UE; telefone não conta). Valores derivados são calculados, nunca gravados. O consentimento de privacidade nunca é lido para a saída.
   * Saída: empresa: id, preparada e lista dos dados obrigatórios que faltam. pessoas: página { items, page, pageSize, hasMore } de pessoas com id, nome, país, situação na plataforma, acesso completo e dados que faltam.
   */
  'inicio.pessoas_organizacao.abrirPessoasOrganizacao': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { empresa: EmpresaPreparo; pessoas: { items: PessoaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['acessoCompletoDadosMinimos', 'empresaPreparadaDadosObrigatorios'];
    access: { actors: ['responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso']; scope: 'organization' };
  };
  /**
   * Finalidade: Procura as pessoas da organização pelo nome e filtra pela situação do acesso, paginando o resultado.
   * Entrada: busca: trecho do nome da pessoa (opcional); situacao: ’todas’, ’acessoIncompleto’ (acessoCompleto falso) ou ’aguardandoLiberacao’ (situação na plataforma diferente de Active); page e pageSize: página pedida e tamanho.
   * Processamento: Restringe às pessoas da organização do responsável logado com papel inicio.PessoaOrganizacao; aplica locate.byName quando há busca; calcula acessoCompleto e dadosFaltantes conforme acessoCompletoDadosMinimos e aplica o filtro de situação sobre esses valores e o status. Ordena com acesso incompleto primeiro e depois por nome. Não lê o consentimento de privacidade.
   * Saída: pessoas: página { items, page, pageSize, hasMore } de pessoas com id, nome, país, situação, acesso completo e dados que faltam.
   */
  'inicio.pessoas_organizacao.buscarPessoas': {
    kind: 'qry';
    input: { busca?: string; situacao?: 'todas' | 'acessoIncompleto' | 'aguardandoLiberacao'; page: number; pageSize: number };
    output: { pessoas: { items: PessoaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['acessoCompletoDadosMinimos'];
    access: { actors: ['responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso']; scope: 'organization' };
  };
  /**
   * Finalidade: Lê a pessoa selecionada com tudo que explica a situação do acesso dela e a etapa da liberação.
   * Entrada: pessoaId: id (mdmId) da pessoa selecionada na lista.
   * Processamento: Lê a pessoa por read.byId, recusando se não pertence à organização do responsável logado. Calcula acessoCompleto e dadosFaltantes conforme acessoCompletoDadosMinimos e consentimentoExigido pelo país (Brasil ou União Europeia), sem expor o conteúdo do consentimento (campo negado pelo grant). Deriva etapaLiberacao de status e acessoCompleto: acessoCompletado se acesso completo; loginLigado se Active com dados faltando; acessoLiberado/pedidoEncaminhado conforme a situação na plataforma; a ligação do login é decidida só pela liberação da plataforma (ligacaoLoginPelaPlataforma) e o endpoint não registra pendência. Não concede papéis nem permissões (dadosNaoConcedemPermissoes).
   * Saída: pessoa: id, nome, país, situação, contatos (e-mail da conta e telefone opcional), acesso completo, dados que faltam, se o consentimento é exigido e a etapa atual da liberação.
   */
  'inicio.pessoas_organizacao.obterPessoa': {
    kind: 'qry';
    input: { pessoaId: string };
    output: { pessoa: PessoaDetalhe };
    rules: ['acessoCompletoDadosMinimos', 'ligacaoLoginPelaPlataforma', 'dadosNaoConcedemPermissoes'];
    access: { actors: ['responsavel']; grants: ['responsavelPrepararEmpresa', 'responsavelAcompanharPessoas', 'responsavelMeuAcesso']; scope: 'organization' };
  };
}
